//! Package 4's site rows (recording, notifications): generated by `tools/gen_sites_pkg4.py` from the
//! owned 13.0.5 `main` (the guard bytes) and checked against it by `tests/input_sites.rs`. The
//! install line reports these after `sites::SITES`.

use super::guard::{HookForm, Placement, SeamKind, GUARD_BYTES};
use super::sites::{Feature, Site};

pub const POSTURE_LR_OFFSET: usize = 0x206af10;
pub const STOP_IS_STOP_OFFSET: usize = 0x20891f0;
pub const WORK_SET_INT_OFFSET: usize = 0x208dbd0;
pub const MODEL_SET_COLOR_RGB_OFFSET: usize = 0x2057790;
pub const FIGHTER_MANAGER_GET_ENTRY_OFFSET: usize = 0x2140f90;
pub const AI_EPILOGUE_OFFSET: usize = 0x2dbc38;
pub const COMBO_DISPLAY_A_OFFSET: usize = 0x13e549c;
pub const COMBO_DISPLAY_B_OFFSET: usize = 0x13e54d8;
pub const STALE_MOVES_TOGGLE_OFFSET: usize = 0x13e88c4;

pub static SITES: [Site; 25] = include!(concat!(env!("OUT_DIR"), "/tables/sites_pkg4.SITES.rs"));

/// The package's sites of one feature (all of them must be usable for the feature to install).
pub fn sites_of(feature: Feature) -> impl Iterator<Item = &'static Site> {
    SITES.iter().filter(move |site| site.feature == feature)
}

const _: () = assert!(GUARD_BYTES == 64);
